1	/* AURORA Dimensional Explorer — vanilla JS, classic scripts (file:// safe).
2	   Architecture: state is owned by clearly named owners; every render is a pure
3	   function of state. Selection attaches to record id, so re-projecting
4	   dimensions never resets cognition (user_job success criterion).
5	   State owners:
6	     projection+scale → app root (undoable via history stack)
7	     filters          → per-dimension controls in the rail, mirrored as chips
8	     selection        → app root Set<recordId>
9	     viewport         → chart axis extents (derived)
10	     inspector/detail → derived from selection                                     */
11	(function () {
12	  'use strict';
13	
14	  var CAT = window.CATALOG;
15	  var DIMS = CAT.dimensions;
16	  var DIM_BY_ID = {};
17	  DIMS.forEach(function (d) { DIM_BY_ID[d.id] = d; });
18	
19	  var DEFAULT_SLOTS = { x: 'radius', y: 'period', color: 'star_class', size: 'mass' };
20	  var DEFAULT_SCALES = { x: 'lin', y: 'log' };
21	
22	  var state = {
23	    slots: { x: DEFAULT_SLOTS.x, y: DEFAULT_SLOTS.y, color: DEFAULT_SLOTS.color, size: DEFAULT_SLOTS.size },
24	    scales: { x: 'lin', y: 'log' },
25	    filters: [],            // [{dim, lo, hi} | {dim, set:Set}] — one owner per dimension
26	    selection: new Set(),   // record ids — survives projection & filter changes
27	    selectedId: null,       // inspector binding (also survives re-projection)
28	    hist: [],               // projection history for undo
29	    sort: { key: 'id', dir: 1 }
30	  };
31	
32	  var el = function (id) { return document.getElementById(id); };
33	  var canvas, ctx, tip;
34	  var geo = null;          // current chart geometry for hit-testing
35	  var hoverId = null;
36	
37	  /* ---------------- scale / format helpers ---------------- */
38	  function fmtVal(dim, v) {
39	    if (v == null || isNaN(v)) return '–';
40	    var s = Number(v).toFixed(dim.fmt != null ? dim.fmt : 2);
41	    return dim.unit ? s + ' ' + dim.unit : s;
42	  }
43	  function val(r, dimId) { return r[dimId]; }
44	  function transform(v, scale) { return scale === 'log' ? Math.log(v) : v; }
45	  function extent(records, dimId, scale) {
46	    var lo = Infinity, hi = -Infinity;
47	    for (var i = 0; i < records.length; i++) {
48	      var v = transform(records[i][dimId], scale);
49	      if (v < lo) lo = v; if (v > hi) hi = v;
50	    }
51	    if (lo === hi) { lo -= 1; hi += 1; }
52	    var pad = (hi - lo) * 0.05;
53	    return [lo - pad, hi + pad];
54	  }
55	  function niceTicks(lo, hi, n, scale) {
56	    var ticks = [], span = hi - lo, step0 = span / n;
57	    var mag = Math.pow(10, Math.floor(Math.log(step0) / Math.LN10));
58	    var norm = step0 / mag;
59	    var step = (norm < 1.5 ? 1 : norm < 3.5 ? 2 : norm < 7.5 ? 5 : 10) * mag;
60	    var t = Math.ceil(lo / step) * step;
61	    for (; t <= hi + 1e-9; t += step) {
62	      var v = scale === 'log' ? Math.exp(t) : t;
63	      ticks.push({ v: v, t: Math.abs(v) >= 1000 ? Math.round(v).toLocaleString('en-US') : String(Math.round(v * 100) / 100) });
64	    }
65	    return ticks;
66	  }
67	
68	  /* ---------------- filtering (owned state) ---------------- */
69	  function matches(r, f) {
70	    var dim = DIM_BY_ID[f.dim];
71	    if (dim.type === 'q') return r[f.dim] >= f.lo && r[f.dim] <= f.hi;
72	    return f.set.has(String(r[f.dim]));
73	  }
74	  function inScope() {
75	    return CAT.records.filter(function (r) { return state.filters.every(function (f) { return matches(r, f); }); });
76	  }
77	  function filterLabel(f) {
78	    var dim = DIM_BY_ID[f.dim];
79	    if (dim.type === 'q') return fmtVal(dim, f.lo).replace(/ /g, '') + '–' + fmtVal(dim, f.hi).replace(/ /g, '');
80	    var vals = dim.cats.filter(function (c) { return f.set.has(c); });

