560	  function boot() {
561	    canvas = el('chart'); tip = el('tooltip');
562	    try { ctx = canvas.getContext('2d'); } catch (err) { ctx = null; }
563	    if (!ctx) el('chart-error').hidden = false;
564	    buildRail();
565	    wireHeader(); wireTable(); wireChart();
566	    if (ctx && 'ResizeObserver' in window) new ResizeObserver(function () { drawWithHover(); }).observe(canvas.parentElement);
567	    window.addEventListener('resize', drawWithHover);
568	    renderAll();                     // synchronous first paint: data is inlined, no loading state
569	    if (new URLSearchParams(location.search).has('test')) runTests();
570	  }
571	
572	  /* ---------------- external API (browser-driven verification) ---------------- */
573	  window.__EXPLORER__ = {
574	    state: function () { return state; },
575	    inScopeCount: function () { return inScope().length; },
576	    select: function (ids) { setSelection(ids, ids[0] || null); renderAll(); },
577	    setSlot: function (slot, dimId) { setSlot(slot, dimId); },
578	    addQFilter: function (dimId, lo, hi) {
579	      var others = state.filters.filter(function (f) { return f.dim !== dimId; });
580	      state.filters = others.concat([{ dim: dimId, lo: lo, hi: hi }]);
581	      renderAll();
582	    },
583	    addCFilter: function (dimId, values) {
584	      var others = state.filters.filter(function (f) { return f.dim !== dimId; });
585	      state.filters = others.concat([{ dim: dimId, set: new Set(values) }]);
586	      renderAll();
587	    },
588	    removeChip: function (i) {
589	      var dimId = state.filters[i].dim;
590	      state.filters.splice(i, 1);
591	      var dim = DIM_BY_ID[dimId];
592	      if (dim.type === 'q') {
593	        var vals = CAT.records.map(function (r) { return r[dimId]; });
594	        el('rf-' + dimId + '-lo').value = Math.min.apply(null, vals);
595	        el('rf-' + dimId + '-hi').value = Math.max.apply(null, vals);
596	      } else document.querySelectorAll('.dim-row[data-dim="' + dimId + '"] input[type="checkbox"]').forEach(function (b) { b.checked = true; });
597	      renderAll();
598	    },
599	    undo: undoProjection,
600	    reset: resetProjection,
601	    clearFilters: function () { el('btn-clear-filters').click(); },
602	    clearSelection: function () { el('btn-clear-selection').click(); },
603	    demo: function () {
604	      // A representative explore moment: select three records, scope by two
605	      // filters, then re-project X — everything else stays put.
606	      this.select(['AUR-1004', 'AUR-1052', 'AUR-1210']);
607	      this.addQFilter('distance', 0, 800);
608	      this.addCFilter('method', ['Transit', 'Radial Velocity']);
609	      this.setSlot('x', 'habit');
610	      return { sel: Array.from(state.selection), filters: state.filters.length, x: state.slots.x };
611	    }
612	  };
613	
614	  /* ---------------- self-test harness (?test) ---------------- */
615	  function runTests() {
616	    var report = el('test-report');
617	    report.hidden = false;
618	    var results = [];
619	    function assert(name, cond, detail) { results.push({ name: name, pass: !!cond, detail: detail || '' }); }
620	    var X = window.__EXPLORER__;
621	
622	    // T1 first paint: ready, no loading state, full scope
623	    assert('T1 first paint ready (no loading state)', document.querySelectorAll('.loading, .skeleton').length === 0
624	      && X.inScopeCount() === CAT.records.length, 'inScope=' + X.inScopeCount());
625	
626	    // T2 selection survives a dimension switch
627	    X.select(['AUR-1000', 'AUR-1010', 'AUR-1020']);
628	    var before = Array.from(X.state().selection).slice().sort();
629	    var selRowsBefore = document.querySelectorAll('#record-table tr.sel').length;
630	    X.setSlot('x', 'temp');
631	    var after = Array.from(X.state().selection).slice().sort();
632	    var selRowsAfter = document.querySelectorAll('#record-table tr.sel').length;
633	    assert('T2 selection survives dimension switch', JSON.stringify(before) === JSON.stringify(after)
634	      && selRowsBefore === selRowsAfter && selRowsAfter === 3,
635	      'rowsBefore=' + selRowsBefore + ' rowsAfter=' + selRowsAfter);
636	
637	    // T3 filters are owned: chips name their owner dimension
638	    X.addQFilter('radius', 1, 4);
639	    X.addCFilter('star_class', ['G', 'K']);
640	    var chips = document.querySelectorAll('#filter-chips .chip');
641	    var ownerTexts = Array.prototype.map.call(chips, function (c) { return c.querySelector('.owner').textContent; });
642	    var scoped = X.inScopeCount();
643	    assert('T3 filter chips exist with owners', chips.length === 2 &&
644	      ownerTexts.indexOf('Planet Radius') >= 0 && ownerTexts.indexOf('Stellar Class') >= 0 && scoped < CAT.records.length,
645	      'chips=' + chips.join(', ') + ' inScope=' + scoped);
646	    assert('T3b selection survived filter changes', document.querySelectorAll('#record-table tr.sel').length === 3,
647	      'selRows=' + document.querySelectorAll('#record-table tr.sel').length);
648	
649	    // T4 removing a chip removes exactly that filter
650	    var beforeScope = X.inScopeCount();
651	    X.removeChip(1); // Stellar Class chip
652	    var chipsAfter = document.querySelectorAll('#filter-chips .chip');
653	    var ownersAfter = Array.prototype.map.call(chipsAfter, function (c) { return c.querySelector('.owner').textContent; });
654	    assert('T4 chip removal reverts exactly one filter', chipsAfter.length === 1 &&
655	      ownersAfter[0] === 'Planet Radius' && X.inScopeCount() > beforeScope,
656	      'inScope ' + beforeScope + '→' + X.inScopeCount());
657	
658	    // T5 projection undo restores the previous projection, touches nothing else
659	    var scopeBeforeUndo = X.inScopeCount();
660	    var xBefore = X.state().slots.x;
661	    var filtersBeforeUndo = X.state().filters.length;
662	    X.setSlot('x', 'mass');
663	    X.undo();
664	    assert('T5 projection undo is per-step and side-effect-free',
665	      X.state().slots.x === xBefore && X.state().filters.length === filtersBeforeUndo
666	      && X.inScopeCount() === scopeBeforeUndo,
667	      'x=' + X.state().slots.x);
668	
669	    // T6 reset restores default slots; undo reverts the reset
670	    X.reset();
671	    var isDefault = X.state().slots.x === 'radius' && X.state().slots.y === 'period';
672	    X.undo();
673	    assert('T6 reset→default and undo→pre-reset', isDefault && X.state().slots.x === 'temp',
674	      'after reset x=radius? ' + isDefault + '; after undo x=' + X.state().slots.x);
675	
676	    // T7 clear-all and clear-selection
677	    X.addCFilter('method', ['Transit']);
678	    X.clearFilters();
679	    X.clearSelection();
680	    assert('T7 clear filters + selection', X.state().filters.length === 0 &&
681	      X.state().selection.size === 0 && X.inScopeCount() === CAT.records.length,
682	      'inScope=' + X.inScopeCount());
683	
684	    var npass = results.filter(function (r) { return r.pass; }).length;
685	    report.innerHTML = '<h3>SELF-TEST ' + npass + '/' + results.length + ' PASS</h3>' +
686	      results.map(function (r) {
687	        return '<div class="tr ' + (r.pass ? 'pass' : 'fail') + '"><span>' + (r.pass ? '✔' : '✘') + '</span><span>' +
688	          r.name + (r.detail ? ' — <i>' + r.detail + '</i>' : '') + '</span></div>';
689	      }).join('') +
690	      '<div class="sum ' + (npass === results.length ? 'pass' : 'fail') + '">' +
691	      (npass === results.length ? 'ALL CHECKS PASS' : 'FAILURES PRESENT') + '</div>';
692	  }
693	
694	  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', boot);
695	  else boot();
696	})();
