1	/* AURORA Exoplanet Catalog — synthetic dataset, deterministically generated (seed 42).
2	   Inlined at load: no fetch, no loading state. Exposed as window.CATALOG. */
3	(function () {
4	  'use strict';
5	
6	  // mulberry32 — small seeded PRNG so the catalog is identical on every load.
7	  function mulberry32(seed) {
8	    var a = seed >>> 0;
9	    return function () {
10	      a |= 0; a = (a + 0x6D2B79F5) | 0;
11	      var t = Math.imul(a ^ (a >>> 15), 1 | a);
12	      t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
13	      return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
14	    };
15	  }
16	
17	  var rand = mulberry32(42);
18	  function gauss(mu, sigma) {
19	    var u = 1 - rand(), v = rand();
20	    return mu + sigma * Math.sqrt(-2 * Math.log(u)) * Math.cos(2 * Math.PI * v);
21	  }
22	  function clamp(v, lo, hi) { return v < lo ? lo : (v > hi ? hi : v); }
23	  function pickWeighted(pairs) {
24	    var r = rand(), acc = 0;
25	    for (var i = 0; i < pairs.length; i++) { acc += pairs[i][1]; if (r <= acc) return pairs[i][0]; }
26	    return pairs[pairs.length - 1][0];
27	  }
28	  function round(v, n) { var m = Math.pow(10, n); return Math.round(v * m) / m; }
29	
30	  var STAR_MASS = { M: [0.30, 0.12], K: [0.70, 0.14], G: [1.00, 0.14], F: [1.28, 0.18], A: [1.85, 0.30] };
31	
32	  var N = 1204;
33	  var records = [];
34	  for (var i = 0; i < N; i++) {
35	    var starClass = pickWeighted([['M', 0.50], ['K', 0.20], ['G', 0.17], ['F', 0.09], ['A', 0.04]]);
36	    var sm = STAR_MASS[starClass];
37	    var starMass = round(clamp(gauss(sm[0], sm[1]), 0.08, 2.6), 2);
38	
39	    var radius = round(clamp(Math.exp(gauss(0.9, 0.8)), 0.3, 45), 2);          // Earth radii
40	    var mass = round(clamp(Math.pow(radius, 1.3) * Math.exp(gauss(0, 0.5)), 0.05, 5200), 2); // Earth masses
41	    var period = round(clamp(Math.exp(gauss(2.2, 1.5)), 0.5, 3200), 2);        // days
42	    var temp = Math.round(clamp(250 + 1200 * Math.pow(period, -0.5) * Math.exp(gauss(0, 0.35)), 20, 3000)); // K
