  }

  /* ---------------- render: filter chips ---------------- */
  function renderChips() {
    var wrap = el('filter-chips');
    if (!state.filters.length) { wrap.innerHTML = '<span class="empty">No active filters — add them from the dimension rail</span>'; return; }
