  var CAT_PALETTE = ['#4ea1ff', '#ffb454', '#58d68d', '#ff7ab6', '#b48cff', '#4dd0e1'];
  var Q_STOPS = [[65, 68, 135], [42, 120, 142], [34, 168, 132], [122, 209, 81], [253, 231, 37]];
