6	const MAX_ENTRIES = 50_000;
7	const MAX_BYTES = 256 * 1024 * 1024;
8	export function isMeasurementExcluded(path) {
9	    return path.split(/[\\/]/).some((name) => EXCLUDED.has(name.toLowerCase()) || /\.(?:log|tmp|tsbuildinfo)$/i.test(name));
10	}
11	/** Hash sorted names and bytes, not timestamps. Never follow tree symlinks. */
12	export async function captureImplementation(root) {
13	    const canonical = await realpath(root);
14	    if (!(await lstat(canonical)).isDirectory())
15	        throw new Error("Implementation root must be a directory");
16	    const hash = createHash("sha256").update("prax-static-tree-v1\0");
17	    let entries = 0;
18	    let bytes = 0;
19	    async function visit(directory, prefix) {
20	        const names = (await readdir(directory)).sort();
21	        for (const name of names) {
22	            if (++entries > MAX_ENTRIES)
23	                throw new Error("Implementation tree exceeds entry limit");
24	            if (isMeasurementExcluded(name))
25	                continue;
26	            const path = join(directory, name);
27	            const stats = await lstat(path);
28	            if (stats.isSymbolicLink())
29	                throw new Error(`Implementation tree contains a symlink: ${prefix}${name}`);
30	            if (stats.isDirectory()) {
31	                await visit(path, `${prefix}${name}/`);
32	            }
33	            else if (stats.isFile()) {
34	                bytes += stats.size;
35	                if (bytes > MAX_BYTES)
36	                    throw new Error("Implementation tree exceeds byte limit");
37	                const content = await readFile(path);
38	                if (content.length !== stats.size)
39	                    throw new Error("Implementation file changed while hashing");
40	                hash.update(JSON.stringify([`${prefix}${name}`, content.length]));
41	                hash.update("\0").update(content).update("\0");
42	            }
43	            else {
44	                throw new Error(`Implementation tree contains a non-regular file: ${prefix}${name}`);
45	            }
46	        }
47	    }
48	    await visit(canonical, "");
49	    return { root: canonical, digest: hash.digest("hex") };
50	}
51	export async function captureContracts(sessionDirectory) {
52	    const result = {};
53	    for (const name of CONTRACT_FILES) {
54	        try {
55	            const path = join(sessionDirectory, name);
56	            const stats = await lstat(path);
57	            if (!stats.isFile() || stats.isSymbolicLink())
58	                throw new Error(`Contract is not a regular file: ${name}`);
