// Focus-order + keyboard-selection measurement for cell-j13-s10-b (runs headless Chrome via playwright).
import { createRequire } from 'node:module';
import { writeFile, mkdir } from 'node:fs/promises';
import { dirname } from 'node:path';

const require = createRequire('file:///E:/codex-prj/pi-m3-frozen-runtime-20260906/package.json');
const { chromium } = require('playwright');
const pwVersion = require('playwright/package.json').version;

const TARGET = 'file:///E:/codex-prj/ab-worktrees/pi-matrix-r2/cell-j13-s10-b/index.html';
const OUT = 'E:\\codex-prj\\ab-worktrees\\pi-matrix-r2\\cell-j13-s10-b\\.prax\\design\\sessions\\ds_20260916203205_d54e8ba3\\validation-evidence\\keyboard-focus-order.json';

const consoleMessages = [];
const pageErrors = [];

const browser = await chromium.launch({ channel: 'chrome', headless: true });
const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
page.on('console', (m) => consoleMessages.push(m.type() + ': ' + m.text()));
page.on('pageerror', (e) => pageErrors.push(String(e)));

await page.goto(TARGET, { waitUntil: 'load' });
await page.waitForFunction(
  () => !!window.__EXPLORER__ && document.querySelectorAll('#record-table tbody tr[data-id]').length > 0,
  null,
  { timeout: 15000 }
);

const readActive = () =>
  page.evaluate(() => {
    const a = document.activeElement;
    return {
      key: a.tagName + '|' + (a.id || '') + '|' + ((a.dataset && a.dataset.id) || '') + '|' + (a.className || ''),
      tag: a.tagName,
      id: a.id || null,
      dataId: (a.dataset && a.dataset.id) || null,
      cls: a.className || null,
      label: ((a.getAttribute('aria-label') || a.textContent) || '').slice(0, 40),
      fv: a.matches(':focus-visible'),
      outlineStyle: getComputedStyle(a).outlineStyle,
      outlineWidth: getComputedStyle(a).outlineWidth
    };
  });

// Sequential focus-order measurement: Tab up to 60 times, stop on consecutive repeat.
const steps = [];
let focusVisible = null;
let prevKey = null;
for (let i = 1; i <= 60; i++) {
  await page.keyboard.press('Tab');
  const info = await readActive();
  steps.push({ step: i, tag: info.tag, id: info.id, dataId: info.dataId, cls: info.cls, label: info.label });
  if (!focusVisible && info.tag !== 'BODY') {
    focusVisible = { matches: info.fv, outlineStyle: info.outlineStyle, outlineWidth: info.outlineWidth };
  }
  if (prevKey !== null && info.key === prevKey) break; // focus repeated the same element twice in a row
  prevKey = info.key;
}

// Keyboard row selection test on the first table row.
const firstRow = page.locator('#record-table tbody tr[data-id]').first();
await firstRow.focus();
const rowFocused = await page.evaluate(() => {
  const a = document.activeElement;
  return { tag: a.tagName, dataId: (a.dataset && a.dataset.id) || null };
});
await page.keyboard.press('Enter');
const enterSize = await page.evaluate(() => window.__EXPLORER__.state().selection.size);
await page.keyboard.press('Escape');
const escapeSize = await page.evaluate(() => window.__EXPLORER__.state().selection.size);

const enterSelects = enterSize === 1;
const escapeClears = escapeSize === 0;
const okFocusVisible = !!focusVisible && focusVisible.matches === true;
const result = okFocusVisible && enterSelects && escapeClears ? 'pass' : 'fail';

const doc = {
  target: TARGET,
  viewport: { width: 1440, height: 900 },
  ran_at: new Date().toISOString(),
  driver: 'playwright-' + pwVersion + ' chrome headless',
  steps,
  focus_visible: focusVisible,
  selection_via_keyboard: { enter_selects: enterSelects, escape_clears: escapeClears },
  result
};

await mkdir(dirname(OUT), { recursive: true });
await writeFile(OUT, JSON.stringify(doc, null, 2), 'utf8');
await browser.close();

console.log(
  JSON.stringify(
    {
      wrote: OUT,
      focusStepsCount: steps.length,
      focusVisible,
      rowFocused,
      selectionKeyboard: { enter_selects: enterSelects, escape_clears: escapeClears, enterSize, escapeSize },
      result,
      driver: doc.driver,
      ran_at: doc.ran_at,
      lastStep: steps[steps.length - 1] || null,
      consoleMessages,
      pageErrors
    },
    null,
    2
  )
);

// Final digests for cell-j13-s10-b: copy evidence, prune obsolete receipts, capture implementation + contract digests, hash validation-evidence.
import { captureImplementation, captureContracts } from 'file:///E:/codex-prj/pi-m3-frozen-runtime-20260906/packages/prax-validator/dist/measurement-binding.js';
import { createHash } from 'node:crypto';
import { readFile, realpath, readdir, copyFile, unlink, lstat } from 'node:fs/promises';
import { realpathSync } from 'node:fs';
import { join } from 'node:path';

const projectRoot = 'E:\\codex-prj\\ab-worktrees\\pi-matrix-r2\\cell-j13-s10-b';
const sessionDir = projectRoot + '\\.prax\\design\\sessions\\ds_20260916203205_d54e8ba3';
const evDir = join(sessionDir, 'validation-evidence');
const evidenceDir = join(projectRoot, '.evidence');

// step 4: copy evidence files into validation-evidence (same names)
const toCopy = [
  '01-initial.png',
  '02-preserved-context.png',
  '03-selftest.png',
  '04-inspector-selected.png',
  'verify-result.json',
  'verify-result-2.json',
  'verify-result-3.json',
  'verify-result-4.json',
  'verify-result-5.json'
];
const copied = [];
const copyErrors = [];
for (const name of toCopy) {
  try {
    await copyFile(join(evidenceDir, name), join(evDir, name));
    copied.push(name);
  } catch (e) {
    copyErrors.push(name + ': ' + (e && e.code ? e.code : String(e)));
  }
}

// step 5: delete superseded receipts
const toDelete = [
  'keyboard-receipt.md',
  'comparison-scan-receipt.md',
  'hierarchy-receipt.md',
  'product-model-receipt.md',
  'filter-state-receipt.md',
  'requirement-alignment-receipt.md'
];
const deleted = [];
const deleteErrors = [];
for (const name of toDelete) {
  try {
    await unlink(join(evDir, name));
    deleted.push(name);
  } catch (e) {
    deleteErrors.push(name + ': ' + (e && e.code ? e.code : String(e)));
  }
}

// step 6: implementation digest, contract digests, realpaths
const impl = await captureImplementation(realpathSync(projectRoot));
const contracts = await captureContracts(sessionDir);
const realPaths = {
  projectRoot: await realpath(projectRoot),
  sessionDir: await realpath(sessionDir)
};

// step 7: sha256 of every file now in validation-evidence
const names = (await readdir(evDir)).sort();
const evidenceHashes = {};
for (const n of names) {
  const p = join(evDir, n);
  const st = await lstat(p);
  if (st.isFile()) {
    evidenceHashes[n] = createHash('sha256').update(await readFile(p)).digest('hex');
  } else {
    evidenceHashes[n] = '<not-a-regular-file>';
  }
}

console.log(
  JSON.stringify(
    {
      copied,
      copyErrors,
      deleted,
      deleteErrors,
      implementationRoot: impl.root,
      implementationDigest: impl.digest,
      contracts,
      realPaths,
      evidenceHashes
    },
    null,
    2
  )
);

